-- CONTENT-040 activation: static approved card definitions and receipt-gated equipment allowlist only.
-- No card ownership, starter grants, inventory, rewards, offers, or acquisition sources are added.
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='45s';
DO $$
DECLARE active_count integer; starter_count integer; starter_hash text;
BEGIN
 IF current_setting('content040.target_project',true) IS DISTINCT FROM 'wkdvdzfkbwvhyjmamrsg'
    OR public.release_scope() IS DISTINCT FROM 'hero-equipment-006'
    OR public.economy_protocol_version() IS DISTINCT FROM 3
    OR to_regnamespace('shop_private') IS NULL
    OR to_regprocedure('shop_private.owned_equipment(uuid,text,text,text)') IS NULL
    OR to_regprocedure('shop_private.equip(uuid,text,text,text)') IS NULL
    OR NOT EXISTS(SELECT 1 FROM shop_private.policy WHERE singleton AND enabled AND catalog_version='ECONOMY-001C:shop:v1')
 THEN RAISE EXCEPTION 'CONTENT-040 TEST target or published shop boundary mismatch' USING ERRCODE='42501'; END IF;
 SELECT count(*) FILTER (WHERE revoked_at IS NULL),count(*) FILTER (WHERE starter AND revoked_at IS NULL),
        md5(jsonb_agg(definition ORDER BY id) FILTER (WHERE starter AND revoked_at IS NULL)::text)
 INTO active_count,starter_count,starter_hash
 FROM economy_private.card_catalog;
 IF active_count<>7 OR starter_count<>7 OR starter_hash IS DISTINCT FROM '76ac2f21f7acf87f43bb52b4660a3a6f'
    OR EXISTS(SELECT 1 FROM economy_private.card_catalog WHERE version='arena-cards-2026-11-09.1-content-040a')
    OR EXISTS(SELECT 1 FROM economy_private.card_catalog WHERE id IN ('arena-card-traveler-charge','arena-card-precise-cut','arena-card-brave-advance','arena-card-perseverance-blow','arena-card-double-charge','arena-card-guard-break','arena-card-decisive-blow','arena-card-guardian-cut','arena-card-last-resistance','arena-card-firm-block','arena-card-prudent-posture','arena-card-traveler-wall','arena-card-reinforced-guard','arena-card-strategic-defense','arena-card-safe-shelter','arena-card-courage-bastion','arena-card-persevering-fortress','arena-card-breathe-observe','arena-card-side-step','arena-card-opponent-reading','arena-card-careful-preparation','arena-card-reposition','arena-card-tactical-planning','arena-card-constant-watch','arena-card-master-strategy','arena-card-regather-strength','arena-card-renewed-courage','arena-card-prudent-recovery','arena-card-persevering-spirit','arena-card-second-wind','arena-card-heroic-endurance','arena-card-unwavering-resolve','arena-card-firm-until-end'))
 THEN RAISE EXCEPTION 'CONTENT-040 TEST catalog baseline changed' USING ERRCODE='42501'; END IF;
 IF md5(replace(pg_get_functiondef('shop_private.owned_equipment(uuid,text,text,text)'::regprocedure),E'\r\n',E'\n')) IS DISTINCT FROM 'e96f80c4050bf43f1634c2456523d1bd'
    OR md5(replace(pg_get_functiondef('shop_private.equip(uuid,text,text,text)'::regprocedure),E'\r\n',E'\n')) IS DISTINCT FROM 'c18863117cff6d450dd6fb289134cd3e'
 THEN RAISE EXCEPTION 'CONTENT-040 TEST equipment boundary changed' USING ERRCODE='42501'; END IF;
END $$;
